// Parse Vipps summary + build idempotent fingerprint (no secrets).
const raw = $input.first().json;
const indicators = raw.status || {};
const description = String(indicators.description || indicators.indicator || 'unknown');
const indicator = String(indicators.indicator || 'unknown');
const components = Array.isArray(raw.components) ? raw.components : [];
const degraded = components.filter(c => {
  const s = (c && c.status) ? String(c.status).toLowerCase() : '';
  return s && s !== 'operational';
}).map(c => c.name || c.id || 'component');

const fingerprint = ['vipps', indicator, description, degraded.slice(0, 8).join('|')].join('::');
const shouldAlert = indicator !== 'none' && indicator !== 'operational';

// Workflow staticData dedup: skip if same fingerprint already posted.
const store = $getWorkflowStaticData('global');
const last = store.lastFingerprint || '';
const lastAt = Number(store.lastPostedAtMs || 0);
const now = Date.now();
const cooldownMs = 30 * 60 * 1000;
const isDup = last === fingerprint && (now - lastAt) < cooldownMs;

if (!isDup && shouldAlert) {
  store.lastFingerprint = fingerprint;
  store.lastPostedAtMs = now;
}

return [{
  json: {
    source: 'vipps-summary',
    indicator,
    description,
    degradedComponents: degraded,
    fingerprint,
    shouldAlert,
    isDuplicate: isDup,
    agePassImpactHint: 'Mulig innvirkning på AgePass-innlogging (Vipps Login / Userinfo).',
    publicStatusUrl: 'https://status.devora.no',
    skip: isDup || !shouldAlert
  }
}];

// Error path: HTTP/Slack failures land here via onError continueErrorOutput.
const item = $input.first().json;
const msg = item.error || item.message || JSON.stringify(item).slice(0, 500);
return [{ json: { errorHandled: true, errorMessage: String(msg), note: 'Do not expose n8n as public status UI.' } }];
